// ============================================================
// MAP DECODE
// ============================================================
function decodeMap(name) {
  const d = MAP_RLE_DATA[name];
  if(!d) return null;
  const flat = [];
  const rle = d.rle;
  for(let i=0;i<rle.length;i+=2) flat.push(...Array(rle[i]).fill(rle[i+1]));
  const map = [];
  for(let y=0;y<d.H;y++) map.push(new Uint8Array(flat.slice(y*d.W,(y+1)*d.W)));
  return {map, W:d.W, H:d.H};
}

// ============================================================
