    drawBtn(px+pw*0.53,bY,pw*0.42,bH,'Ready',C.hud,'#ccc');
    ctx.fillStyle='#ffcc00'; ctx.font=`bold ${fs*0.9}px 'Courier New'`;
    ctx.fillText('▶ Click on land to place a nation',cx2,py+ph*0.65);
