// ---- GAME ----
function renderGame(){
  drawFrame(); renderMapTiles(); renderNations(); renderCities(); renderHUD();
  if(selectedNation&&selectedNation.alive) renderNationPanel();
  if(sizeMenuOpen) renderLeaderboard('Size',nations.filter(n=>n.alive).sort((a,b)=>b.size-a.size),n=>`${n.name} (${n.size})`, 'chartScrollSize');
  if(ageMenuOpen) renderLeaderboard('Age',nations.filter(n=>n.alive).sort((a,b)=>b.age-a.age),n=>`${n.name} (${n.age})`, 'chartScrollAge');
  if(goldMenuOpen) renderLeaderboard('Gold',nations.filter(n=>n.alive).sort((a,b)=>b.money-a.money),n=>`${n.name} (${Math.floor(n.money)})`, 'chartScrollGold');
  if(inGameMenuOpen) renderInGameMenu();
  if(allySelectMode) renderAllySelectOverlay();
  if(renameActive) renderRenameBox();
  renderPopups();
}

function renderFrame(){ drawFrame(); }

function drawFrame(){
  const r=getMapRect();
  const pad=Math.min(canvas.width,canvas.height)*0.05;
  ctx.fillStyle=C.frame;
  ctx.fillRect(r.x-pad,r.y-pad,r.w+pad*2,r.h+pad*2);
  ctx.fillStyle=C.ocean; ctx.fillRect(r.x,r.y,r.w,r.h);
  ctx.strokeStyle='#6a3020'; ctx.lineWidth=2; ctx.strokeRect(r.x,r.y,r.w,r.h);
  const kr=pad*0.65;
  for(const [kx,ky] of [[r.x-pad,r.y-pad],[r.x+r.w+pad,r.y-pad],[r.x-pad,r.y+r.h+pad],[r.x+r.w+pad,r.y+r.h+pad]]){
    ctx.beginPath(); ctx.arc(kx,ky,kr,0,Math.PI*2);
    ctx.fillStyle='#2a0e04'; ctx.fill();
    ctx.strokeStyle='#7a4028'; ctx.lineWidth=2; ctx.stroke();
  }
}

function renderMapTiles(){
  const r=getMapRect();
  const baseScale=Math.min(r.w/(mapW*TILE_SIZE),r.h/(mapH*TILE_SIZE));
  const ts=TILE_SIZE*baseScale*cameraScale;
  const offX=r.x+(r.w-mapW*ts)/2, offY=r.y+(r.h-mapH*ts)/2;
  ctx.save(); ctx.beginPath(); ctx.rect(r.x,r.y,r.w,r.h); ctx.clip();
  ctx.fillStyle=C.ocean; ctx.fillRect(offX+cameraX,offY+cameraY,mapW*ts,mapH*ts);
  for(let y=0;y<mapH;y++) for(let x=0;x<mapW;x++){
    const v=mapData[y][x]; if(!v) continue;
    if(v===2){
      const owner=getOwner(x,y);
      if(owner) continue;
      if(!showCrossings) continue;
      ctx.fillStyle='#aaaaaa';
    } else {
      ctx.fillStyle=C.land;
    }
    ctx.fillRect(offX+cameraX+x*ts,offY+cameraY+y*ts,Math.ceil(ts)+0.5,Math.ceil(ts)+0.5);
  }
  ctx.restore();
}

function renderNations(){
  const r=getMapRect();
  const baseScale=Math.min(r.w/(mapW*TILE_SIZE),r.h/(mapH*TILE_SIZE));
  const ts=TILE_SIZE*baseScale*cameraScale;
  const offX=r.x+(r.w-mapW*ts)/2, offY=r.y+(r.h-mapH*ts)/2;
  ctx.save(); ctx.beginPath(); ctx.rect(r.x,r.y,r.w,r.h); ctx.clip();
  for(const n of nations){
    if(!n.alive||!n.tiles.size) continue;
    ctx.fillStyle=n.color;
    for(const k of n.tiles){
      const {x,y}=tfk(k);
      if(mapData[y][x]===1){
        ctx.fillRect(offX+cameraX+x*ts,offY+cameraY+y*ts,Math.ceil(ts)+0.5,Math.ceil(ts)+0.5);
      }
    }
    ctx.globalAlpha=0.52;
    for(const k of n.tiles){
      const {x,y}=tfk(k);
      if(mapData[y][x]===2){
        ctx.fillRect(offX+cameraX+x*ts,offY+cameraY+y*ts,Math.ceil(ts)+0.5,Math.ceil(ts)+0.5);
      }
    }
    ctx.globalAlpha=1.0;
    const landSize=[...n.tiles].filter(k=>{const{x,y}=tfk(k);return mapData[y][x]===1;}).length;
    if(landSize>4||n.tiles.size>4){
      const c=getNationCentroid(n);
      const sx=offX+cameraX+c.x*ts+ts/2, sy=offY+cameraY+c.y*ts;
      const lfs=Math.max(8,ts*1.3);
      ctx.font=`bold ${lfs}px 'Courier New'`; ctx.textAlign='center';
      ctx.fillStyle='rgba(0,0,0,0.7)'; ctx.fillText(n.name,sx+1,sy+1);
      ctx.fillStyle='#fff'; ctx.fillText(n.name,sx,sy);
    }
  }
  ctx.restore();
}

function getNationCentroid(n){
  let sx=0,sy=0,c=0,i=0;
  const step=Math.max(1,Math.floor(n.tiles.size/300));
  for(const k of n.tiles){if(i%step===0){const t=tfk(k);sx+=t.x;sy+=t.y;c++;}i++;}
  return c?{x:sx/c,y:sy/c}:{x:0,y:0};
}

function renderCities(){
  const r=getMapRect();
  const baseScale=Math.min(r.w/(mapW*TILE_SIZE),r.h/(mapH*TILE_SIZE));
  const ts=TILE_SIZE*baseScale*cameraScale;
  const offX=r.x+(r.w-mapW*ts)/2, offY=r.y+(r.h-mapH*ts)/2;
  ctx.save(); ctx.beginPath(); ctx.rect(r.x,r.y,r.w,r.h); ctx.clip();
  for(const city of cities){
    const sx=offX+cameraX+city.x*ts+ts/2, sy=offY+cameraY+city.y*ts+ts/2;
    const cr=Math.max(3,ts*0.65);
    
    // Revolt effects
    if(city.revoltChance > 65){
      ctx.beginPath(); ctx.arc(sx,sy,cr*2.5,0,Math.PI*2);
      ctx.strokeStyle='rgba(255,0,0,'+(0.2 + Math.sin(Date.now()/200)*0.1)+')';
      ctx.lineWidth=2; ctx.stroke();
    }

    // City dot
    ctx.beginPath(); ctx.arc(sx,sy,cr+1,0,Math.PI*2); ctx.fillStyle='#000'; ctx.fill();
    ctx.beginPath(); ctx.arc(sx,sy,cr,0,Math.PI*2);
    if(city.capital) ctx.fillStyle='#e04040';
    else if(city.cored) ctx.fillStyle='#50c050';
    else ctx.fillStyle='#ffffff';
    ctx.fill();

    const lfs=Math.max(7,ts*1.1);
    ctx.font=`${lfs}px 'Courier New'`; ctx.textAlign='center';
    ctx.fillStyle='rgba(0,0,0,0.7)'; ctx.fillText(city.name,sx+1,sy-cr-2);
    ctx.fillStyle='#fff'; ctx.fillText(city.name,sx,sy-cr-3);
  }
  ctx.restore();
  if(selectedCity) renderCityMenu();
}

