  drawBtn(bX, py+ph*0.2, bW, bH, 'Rename', C.hud, '#ccc');
  drawBtn(bX, py+ph*0.3, bW, bH, c.capital?'Is Capital':'Make Capital', c.capital?'#602020':'#802020', '#fff');
