function renderHUD(){
  const hh=canvas.height*0.068, hy=canvas.height-hh;
  ctx.fillStyle=C.hud; ctx.fillRect(0,hy,canvas.width,hh);
  ctx.fillStyle=C.hudLight; ctx.fillRect(0,hy,canvas.width,3);
  const bh=hh*0.72, by=hy+hh/2-bh/2;
  const bw=canvas.width*0.082, gap=canvas.width*0.006;
  const leftBtns=[
    ['Popups',showPopups],['Crossings',showCrossings],['Pause',!simRunning]
  ];
  leftBtns.forEach(([lbl,act],i)=>{
    hudBtn(gap+i*(bw+gap),by,bw,bh,lbl,act);
  });
  const rs=canvas.width-gap;
  hudBtn(rs-bw,by,bw,bh,'⏻',false,'power');
  ctx.fillStyle='#ccc'; ctx.font=`${hh*0.3}px 'Courier New'`; ctx.textAlign='right';
  ctx.fillText(`Year: ${year}`,rs-bw-gap*2,hy+hh*0.65);
  hudBtn(rs-bw*3.5-gap*3,by,bw*1.3,bh,'Age',ageMenuOpen);
  hudBtn(rs-bw*5.1-gap*4,by,bw*1.3,bh,'Gold',goldMenuOpen);
  hudBtn(rs-bw*6.7-gap*5,by,bw*1.3,bh,'Size',sizeMenuOpen);
  const spx=rs-bw*8.7-gap*6;
  ctx.fillStyle=C.hudLight; ctx.fillRect(spx,by,bw*1.8,bh);
  ctx.strokeStyle=C.panelBorder; ctx.lineWidth=1; ctx.strokeRect(spx,by,bw*1.8,bh);
  ctx.fillStyle='#fff'; ctx.font=`${hh*0.32}px 'Courier New'`; ctx.textAlign='center';
  ctx.fillText(`◄ Speed:${simSpeed}x ►`,spx+bw*0.9,by+bh*0.68);
}

function hudBtn(x,y,w,h,label,active){
  ctx.fillStyle=active?'#903020':C.hudLight; ctx.fillRect(x,y,w,h);
  ctx.strokeStyle=C.panelBorder; ctx.lineWidth=1; ctx.strokeRect(x,y,w,h);
  ctx.beginPath(); ctx.arc(x+w-w*0.16,y+h/2,h*0.17,0,Math.PI*2);
  ctx.fillStyle=active?'#ff5040':'#503020'; ctx.fill();
  ctx.fillStyle='#ccc'; ctx.font=`${h*0.38}px 'Courier New'`; ctx.textAlign='center';
  ctx.fillText(label,x+w*0.44,y+h*0.67);
}

function renderNationPanel(){
  const n=selectedNation;
  const cw=canvas.width, ch=canvas.height;
  const pw=Math.min(cw*0.18,220), ph=ch*0.55;
  const px=cw*0.006, py=ch*0.025;
  drawPanel(px,py,pw,ph);
  const fs=Math.min(pw*0.065,11);
  ctx.textAlign='left'; ctx.fillStyle='#fff';

  // Name (truncated)
  ctx.font=`bold ${fs*1.15}px 'Courier New'`;
  const dispName=n.name.length>18?n.name.slice(0,16)+'…':n.name;
  ctx.fillText(dispName,px+pw*0.06,py+ph*0.055);

  // Rename button
  drawBtn(px+pw*0.05,py+ph*0.075,pw*0.6,ph*0.055,'Rename',C.hud,'#ccc');

  // Status rows
  const rows=[
    {col:'#50c8c8',txt:`Age: ${n.age} | Wars: ${n.wars.length}`},
    {col:'#50c850',txt:n.parentNation?`Revolted: ${n.parentNation.name.slice(0,10)}`:'Origin nation'},
    {col:'#e04040',txt:n.alive?'Alive':'Destroyed'},
    {col:'#5080e0',txt:n.allies.length?`Allies: ${n.allies.map(a=>a.name.slice(0,6)).join(',')}`:'No allies'},
  ];
  rows.forEach((row,i)=>{
    const ry=py+ph*0.175+i*ph*0.075;
    ctx.fillStyle=row.col; ctx.fillRect(px+pw*0.04,ry-fs*0.75,pw*0.05,fs*0.8);
    ctx.fillStyle='#ddd'; ctx.font=`${fs*0.82}px 'Courier New'`;
    fitText(row.txt,px+pw*0.12,ry,pw*0.84,fs*0.82,'left');
  });

  // Gold & stats
  const sy=py+ph*0.49;
  ctx.fillStyle=C.gold; ctx.font=`bold ${fs*1.05}px 'Courier New'`;
  ctx.fillText(`⬡ ${Math.floor(n.money)}`,px+pw*0.06,sy);
  ctx.fillStyle='#ddd'; ctx.font=`${fs*0.82}px 'Courier New'`;
  ctx.fillText(`CE: ${n.combatEfficiency}/6`,px+pw*0.06,sy+ph*0.07);
  ctx.fillText(`Size: ${n.size}`,px+pw*0.06,sy+ph*0.13);
  ctx.fillText(`Revolts: ${n.revolts}`,px+pw*0.06,sy+ph*0.19);
  const rc=Math.min(99,Math.floor(n.size/50));
  ctx.fillText(`Revolt chance: ${rc}%`,px+pw*0.06,sy+ph*0.25);
  if(n.overlord) ctx.fillText(`Puppet of: ${n.overlord.name.slice(0,12)}`,px+pw*0.06,sy+ph*0.31);

  // God mode buttons
  ctx.fillStyle='#aaa'; ctx.font=`${fs*0.78}px 'Courier New'`; ctx.textAlign='center';
  ctx.fillText('— God Mode —',px+pw/2,py+ph*0.77);
  const gbw=pw*0.42, gbh=ph*0.065, gby=py+ph*0.8, gbgap=pw*0.1;
  drawBtn(px+gbgap,gby,gbw,gbh,'⚔ Attack','#802020','#fff');
  drawBtn(px+gbgap+gbw+pw*0.05,gby,gbw,gbh,'🕊 Peace',C.hud,'#ccc');
  drawBtn(px+gbgap,gby+gbh+ph*0.015,gbw,gbh,'🤝 Ally','#204080','#fff');
  drawBtn(px+gbgap+gbw+pw*0.05,gby+gbh+ph*0.015,gbw,gbh,'💔 Break',C.hud,'#ccc');
  drawBtn(px+gbgap,gby+gbh*2+ph*0.03,pw*0.88,gbh,'⚡ Revolt','#604010','#fff');
}

function renderLeaderboard(title,sorted,labelFn,scrollVar){
  const cw=canvas.width, ch=canvas.height;
  const pw=Math.min(cw*0.21,250), ph=ch*0.55;
  const px=cw-pw-cw*0.006, py=ch*0.08;
  drawPanel(px,py,pw,ph);
  const fs=Math.min(cw*0.011,10);
  ctx.fillStyle='#fff'; ctx.textAlign='left';
  ctx.font=`bold ${fs*1.1}px 'Courier New'`;
  ctx.fillText(title,px+pw*0.05,py+ph*0.065);
  const barCount=14;
  const barTotalH=ph*0.84;
  const barH=(barTotalH/barCount)*0.82;
  const maxVal=sorted.length>0?(title==='Size'?sorted[0].size:(title==='Age'?sorted[0].age:sorted[0].money)):1;
  const scrollOffset=window[scrollVar]||0;
  ctx.save();
  ctx.beginPath(); ctx.rect(px,py+ph*0.1,pw,ph*0.85); ctx.clip();
  for(let i=0;i<sorted.length;i++){
    const n=sorted[i];
    const bary=py+ph*0.1+i*(barTotalH/barCount)-scrollOffset;
    if(bary+barH<py+ph*0.1||bary>py+ph*0.95) continue;
    const val=title==='Size'?n.size:(title==='Age'?n.age:n.money);
    const barW=pw*0.9*(val/Math.max(1,maxVal));
    ctx.fillStyle=n.color; ctx.fillRect(px+pw*0.05,bary,barW,barH);
    ctx.fillStyle='rgba(0,0,0,0.6)';
    ctx.font=`${Math.min(barH*0.7,fs*0.9)}px 'Courier New'`;
    ctx.fillText(labelFn(n),px+pw*0.07,bary+barH*0.78);
  }
  ctx.restore();
}

